func testEquipamentoProcessoEquToManyAddOpEpeProdutoProcessos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a EquipamentoProcessoEqu
	var b, c, d, e ProdutoProcesso

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, equipamentoProcessoEquDBTypes, false, strmangle.SetComplement(equipamentoProcessoEquPrimaryKeyColumns, equipamentoProcessoEquColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*ProdutoProcesso{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, produtoProcessoDBTypes, false, strmangle.SetComplement(produtoProcessoPrimaryKeyColumns, produtoProcessoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*ProdutoProcesso{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddEpeProdutoProcessos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.EpeID != first.EpeID {
			t.Error("foreign key was wrong value", a.EpeID, first.EpeID)
		}
		if a.EpeID != second.EpeID {
			t.Error("foreign key was wrong value", a.EpeID, second.EpeID)
		}

		if first.R.Epe != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Epe != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.EpeProdutoProcessos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.EpeProdutoProcessos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.EpeProdutoProcessos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
