func testEquipamentoProcessoEquToOneSetOpEquipamentoUsingEqu(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a EquipamentoProcessoEqu
	var b, c Equipamento

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, equipamentoProcessoEquDBTypes, false, strmangle.SetComplement(equipamentoProcessoEquPrimaryKeyColumns, equipamentoProcessoEquColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, equipamentoDBTypes, false, strmangle.SetComplement(equipamentoPrimaryKeyColumns, equipamentoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, equipamentoDBTypes, false, strmangle.SetComplement(equipamentoPrimaryKeyColumns, equipamentoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*Equipamento{&b, &c} {
		err = a.SetEqu(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.Equ != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.EquEquipamentoProcessoEqus[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if a.EquID != x.EquID {
			t.Error("foreign key was wrong value", a.EquID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.EquID))
		reflect.Indirect(reflect.ValueOf(&a.EquID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if a.EquID != x.EquID {
			t.Error("foreign key was wrong value", a.EquID, x.EquID)
		}
	}
}
